package com.zomiggy.entity;
import jakarta.persistence.*;
@Entity public class Dish { @Id private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Restaurant restaurant; @Column(nullable=false) private String name; @Column(nullable=false) private String category; @Column(nullable=false) private int price; private double rating; private String time; private boolean veg; private boolean healthy; private String badge; @Column(length=1000) private String description; private String imageUrl; protected Dish(){} public Dish(long id,Restaurant r,String name,String category,int price,double rating,String time,boolean veg,boolean healthy,String badge,String description,String imageUrl){this.id=id;this.restaurant=r;this.name=name;this.category=category;this.price=price;this.rating=rating;this.time=time;this.veg=veg;this.healthy=healthy;this.badge=badge;this.description=description;this.imageUrl=imageUrl;} public Long getId(){return id;} public Restaurant getRestaurant(){return restaurant;} public String getName(){return name;} public String getCategory(){return category;} public int getPrice(){return price;} public double getRating(){return rating;} public String getTime(){return time;} public boolean isVeg(){return veg;} public boolean isHealthy(){return healthy;} public String getBadge(){return badge;} public String getDescription(){return description;} public String getImageUrl(){return imageUrl;} }